@@ -0,0 +1,77 @@
+import { renderHook } from '@tests/utils';
+
+import { useTracking, MEDIA_LIBRARY_VERSION } from '../useTracking';
+
+const mockTrackStrapiUsage = jest.fn();
+const mockUseAIAvailability = jest.fn();
+const mockUseGetSettingsQuery = jest.fn();
+
+jest.mock('@strapi/admin/strapi-admin', () => ({
+  ...jest.requireActual('@strapi/admin/strapi-admin'),
+  useTracking: () => ({ trackUsage: mockTrackStrapiUsage }),
+}));
+
+jest.mock('@strapi/admin/strapi-admin/ee', () => ({
+  ...jest.requireActual('@strapi/admin/strapi-admin/ee'),
+  useAIAvailability: () => mockUseAIAvailability(),
+}));
+
+jest.mock('../../services/settings', () => ({
+  useGetUploadSettingsQuery: () => mockUseGetSettingsQuery(),
+}));
+
+describe('future media library useTracking', () => {
+  beforeEach(() => {
+    jest.clearAllMocks();
+    mockUseAIAvailability.mockReturnValue(false);
+    mockUseGetSettingsQuery.mockReturnValue({ data: { data: { aiMetadata: false } } });
+  });
+
+  it('stamps mediaLibraryVersion on every event and forwards name + properties', () => {
+    const { result } = renderHook(() => useTracking());
+
+    result.current.trackUsage('didCropFile', { location: 'upload', duplicatedFile: false });
+
+    expect(mockTrackStrapiUsage).toHaveBeenCalledWith('didCropFile', {
+      location: 'upload',
+      duplicatedFile: false,
+      mediaLibraryVersion: MEDIA_LIBRARY_VERSION,
+    });
+  });
+
+  it('still stamps the version on events fired without properties', () => {
+    const { result } = renderHook(() => useTracking());
+
+    result.current.trackUsage('didSelectAllMediaLibraryElements');
+
+    expect(mockTrackStrapiUsage).toHaveBeenCalledWith('didSelectAllMediaLibraryElements', {
+      mediaLibraryVersion: MEDIA_LIBRARY_VERSION,
+    });
+  });
+
+  it('adds isAiMediaLibraryConfigured when AI is available (mirrors the legacy wrapper)', () => {
+    mockUseAIAvailability.mockReturnValue(true);
+    mockUseGetSettingsQuery.mockReturnValue({ data: { data: { aiMetadata: true } } });
+
+    const { result } = renderHook(() => useTracking());
+
+    result.current.trackUsage('didReplaceMedia', { location: 'upload' });
+
+    expect(mockTrackStrapiUsage).toHaveBeenCalledWith('didReplaceMedia', {
+      location: 'upload',
+      isAiMediaLibraryConfigured: true,
+      mediaLibraryVersion: MEDIA_LIBRARY_VERSION,
+    });
+  });
+
+  it('omits isAiMediaLibraryConfigured when AI is unavailable', () => {
+    const { result } = renderHook(() => useTracking());
+
+    result.current.trackUsage('didReplaceMedia', { location: 'upload' });
+
+    expect(mockTrackStrapiUsage).toHaveBeenCalledWith(
+      'didReplaceMedia',
+      expect.not.objectContaining({ isAiMediaLibraryConfigured: expect.anything() })
+    );
+  });
+});

diff --git a/packages/core/upload/admin/src/future/hooks/useTracking.ts b/packages/core/upload/admin/src/future/hooks/useTracking.ts
--- a/packages/core/upload/admin/src/future/hooks/useTracking.ts
+++ b/packages/core/upload/admin/src/future/hooks/useTracking.ts
@@ -0,0 +1,54 @@
+import { useCallback } from 'react';
+
+import { useTracking as useStrapiTracking, type TrackingEvent } from '@strapi/admin/strapi-admin';
+import { useAIAvailability } from '@strapi/admin/strapi-admin/ee';
+
+import { useGetUploadSettingsQuery } from '../services/settings';
+
+/**
+ * Media Library version tag stamped on every event fired from the new
+ * (`src/future`) Media Library. Legacy events omit it, so analytics can filter
+ * new usage from the old plan while both trees emit the SAME event names (see
+ * CMS-246). Bump this if a future revamp ever needs its own bucket.
+ */
+export const MEDIA_LIBRARY_VERSION = 'v2';
+
+/**
+ * `location` value for every new Media Library event. The new tree is the
+ * standalone Media Library page, which the legacy plan tags `'upload'` (as
+ * opposed to `'content-manager'` for the asset-picker modal). Kept identical so
+ * migrated events line up with the legacy ones on the `location` axis.
+ */
+export const MEDIA_LIBRARY_LOCATION = 'upload';
+
+/**
+ * Tracking wrapper scoped to the new Media Library. Mirrors the legacy
+ * `admin/src/hooks/useTracking` — it forwards to the admin `trackUsage` and
+ * injects `isAiMediaLibraryConfigured` when AI is available — and additionally
+ * stamps `mediaLibraryVersion` on every event so the migrated plan stays
+ * distinguishable from the legacy one.
+ *
+ * The cast mirrors the legacy wrapper: these two properties are cross-cutting
+ * media-tracking metadata that the admin `TrackingEvent` type does not (and
+ * should not) enumerate per event.
+ */
+export const useTracking = () => {
+  const { trackUsage: trackStrapiUsage } = useStrapiTracking();
+  const { data } = useGetUploadSettingsQuery();
+  const isAiAvailable = useAIAvailability();
+
+  // Memoised so consumers can safely list `trackUsage` in effect deps (the
+  // search-input debounce commit does) without re-firing every render.
+  const trackUsage = useCallback(
+    <TEvent extends TrackingEvent>(event: TEvent['name'], properties?: TEvent['properties']) => {
+      return trackStrapiUsage(event, {
+        ...properties,
+        ...(isAiAvailable ? { isAiMediaLibraryConfigured: Boolean(data?.data?.aiMetadata) } : {}),
+        mediaLibraryVersion: MEDIA_LIBRARY_VERSION,
+      } as TEvent['properties']);
+    },
+    [trackStrapiUsage, isAiAvailable, data]
+  );
+
+  return { trackUsage };
+};

