+ * @returns {number}
+ */
+function countValueLeadingGreaterThan(line) {
+  let count = 0;
+
+  for (const character of line) {
+    if (character === ">") {
+      count++;
+    } else if (character !== " " && character !== "\t") {
+      break;
+    }
+  }
