+    if (index === 0) {
+      return rawLine;
+    }
+    const valueMarkerCount = countValueLeadingGreaterThan(valueLine);
+    return removeBlockquoteMarkers(rawLine, valueMarkerCount);
+  });
+  return resultLines.join("\n");
